SINA_SMART["physio-bioen-intro"] = {"lecture":"physio-bioen-intro","title":"Bioenergetics 1: introduction","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physio-bioen-intro:e0","text":"Metabolism = sum of chemical reactions; balance of catabolism and anabolism.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"physio-bioen-intro:e1","text":"Catabolism: breaks down, exergonic, exothermic. Anabolism: builds up, endergonic, endothermic.","topic":"Catabolism and anabolism","sec":1,"importance":"core","highYield":"untested"},{"id":"physio-bioen-intro:e2","text":"ATP couples catabolism to anabolism; enzymes decide which reactions run.","topic":"Catabolism and anabolism","sec":1,"importance":"core","highYield":"untested"},{"id":"physio-bioen-intro:e3","text":"Macronutrients: water, carbohydrates, lipids, proteins. Micronutrients: vitamins, minerals.","topic":"Nutrients","sec":2,"importance":"core","highYield":"untested"},{"id":"physio-bioen-intro:e4","text":"Essential = cannot be made: minerals, most vitamins, 9 amino acids, omega-6 and omega-3, water.","topic":"Essential nutrients and RDAs","sec":3,"importance":"core","highYield":"untested"},{"id":"physio-bioen-intro:e5","text":"Essential nutrients: which (same for all). RDA: how much (varies).","topic":"Essential nutrients and RDAs","sec":3,"importance":"core","highYield":"untested"},{"id":"physio-bioen-intro:e6","text":"1 calorie: 1 g water by 1 °C; 1 kcal = 1 Calorie.","topic":"Calories","sec":4,"importance":"core","highYield":"untested"},{"id":"physio-bioen-intro:e7","text":"Sugar and alcohol (7 kcal/g): empty calories.","topic":"Calories","sec":4,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"1pdo6q7":"a","1oatpy4":"a","1eoflmq":"a","7y2h4":"a","1ujgp9t":"a","w16zq6":"a","nbypob":"a","1xeprbh":"a","ybd8e9":"a","1072s83":"a","mp8sjo":"a","1ruvess":"a","1yn3sfn":"a","x8bov4":"a","a0f71u":"a","1skrnf":"a","abivfg":"a"},"mapCounts":{"verified":0,"auto":17,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physio-bioen-intro:e0":{"s":0,"u":["Metabolism = sum of chemical reactions; balance of catabolism and anabolism.","Metabolism is the sum of all the body's chemical reactions: an energy-balancing act between catabolism (breaking down, releases energy) and anabolism (building up, uses energy)."],"dp":[]},"physio-bioen-intro:e1":{"s":1,"u":["Catabolism: breaks down, exergonic, exothermic. Anabolism: builds up, endergonic, endothermic.","Energy: Catabolism = Provides more than it consumes: exergonic; Anabolism = Consumes more than it produces: endergonic.","Heat: Catabolism = Liberates heat: exothermic; Anabolism = Absorbs heat: endothermic."],"dp":[]},"physio-bioen-intro:e2":{"s":1,"u":["ATP couples catabolism to anabolism; enzymes decide which reactions run.","Which reactions occur depends on which enzymes are active in a cell at that time.","ATP (adenosine triphosphate) is the molecule most often used in energy exchanges: it temporarily stores energy from catabolic reactions and transfers it to anabolic reactions."],"dp":[]},"physio-bioen-intro:e3":{"s":2,"u":["Macronutrients: water, carbohydrates, lipids, proteins. Micronutrients: vitamins, minerals.","Water, carbohydrates, lipids, proteins: Vitamins, minerals.","The six essential nutrient classes : carbohydrates, proteins, fats, water, vitamins, minerals."],"dp":[]},"physio-bioen-intro:e4":{"s":3,"u":["Essential = cannot be made: minerals, most vitamins, 9 amino acids, omega-6 and omega-3, water.","Most vitamins : A, C, D, E, K, B complex Nine amino acids : histidine, isoleucine, leucine, lysine, methionine, phenylalanine, threonine, tryptophan, valine Fatty acids : linoleic acid ( omega-6 ), alpha-linolenic acid ( omega-3 ) Water must be consumed in the diet","Essential nutrients cannot be synthesised by the body : Minerals : calcium, phosphorus, magnesium, iron, zinc, iodine, selenium..."],"dp":[]},"physio-bioen-intro:e5":{"s":3,"u":["Essential nutrients: which (same for all). RDA: how much (varies).","Defines which nutrients are necessary: Defines how much is needed.","Same for all humans: Varies with age, sex, pregnancy and other factors."],"dp":[]},"physio-bioen-intro:e6":{"s":4,"u":["1 calorie: 1 g water by 1 °C; 1 kcal = 1 Calorie.","1 000 calories = 1 kilocalorie (kcal) in physiology = 1 Calorie in dietetics.","One calorie = heat needed to raise 1 g of water by 1 °C ."],"dp":[]},"physio-bioen-intro:e7":{"s":4,"u":["Sugar and alcohol (7 kcal/g): empty calories.","Sugar and alcohol (alcohol 7 kcal/g) are 'empty' calories : few nutrients, and they suppress appetite.","1 000 calories = 1 kilocalorie (kcal) in physiology = 1 Calorie in dietetics."],"dp":[]}},"meta":{"1pdo6q7":{"a":"recall","vg":"physio-bioen-intro:e0/recall/1"},"1oatpy4":{"a":"recall","vg":"physio-bioen-intro:e1/recall/1"},"1eoflmq":{"a":"recall","vg":"physio-bioen-intro:e2/recall/1"},"7y2h4":{"a":"recall","vg":"physio-bioen-intro:e2/recall/2"},"1ujgp9t":{"a":"recall","vg":"physio-bioen-intro:e2/recall/3"},"w16zq6":{"a":"recall","vg":"physio-bioen-intro:e3/recall/1"},"nbypob":{"a":"recall","vg":"physio-bioen-intro:e3/recall/1"},"1xeprbh":{"a":"recall","vg":"physio-bioen-intro:e4/recall/1"},"ybd8e9":{"a":"recall","vg":"physio-bioen-intro:e4/recall/1"},"1072s83":{"a":"recall","vg":"physio-bioen-intro:e4/recall/2"},"mp8sjo":{"a":"recall","vg":"physio-bioen-intro:e4/recall/3"},"1ruvess":{"a":"relationship","vg":"physio-bioen-intro:e5/relationship/1"},"1yn3sfn":{"a":"recall","vg":"physio-bioen-intro:e6/recall/1"},"x8bov4":{"a":"recall","vg":"physio-bioen-intro:e6/recall/2"},"a0f71u":{"a":"recall","vg":"physio-bioen-intro:e7/recall/1"},"1skrnf":{"a":"recall","vg":"physio-bioen-intro:e7/recall/2"},"abivfg":{"a":"recall","vg":"physio-bioen-intro:e4/recall/4"}},"explRev":"472bc01d89b7"};
